create table public.party_votes(id uuid primary key default gen_random_uuid(),party_id uuid not null references public.persistent_parties(id)on delete cascade,created_by_user_id uuid not null references auth.users(id)on delete cascade,created_by_character_id uuid not null references public.characters(id)on delete cascade,question text not null check(char_length(question)between 3 and 160),status text not null default'open'check(status in('open','closed')),winning_option_id uuid,closes_at timestamptz not null,created_at timestamptz not null default now(),closed_at timestamptz);
create table public.party_vote_options(id uuid primary key default gen_random_uuid(),vote_id uuid not null references public.party_votes(id)on delete cascade,label text not null check(char_length(label)between 1 and 60),position smallint not null check(position between 1 and 4),unique(vote_id,position));
alter table public.party_votes add constraint party_votes_winner_fkey foreign key(winning_option_id)references public.party_vote_options(id);
create table public.party_vote_ballots(id uuid primary key default gen_random_uuid(),vote_id uuid not null references public.party_votes(id)on delete cascade,option_id uuid not null references public.party_vote_options(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,character_id uuid not null references public.characters(id)on delete cascade,voted_at timestamptz not null default now(),unique(vote_id,user_id));
alter table public.party_votes enable row level security;alter table public.party_vote_options enable row level security;alter table public.party_vote_ballots enable row level security;
create policy "Party members can read votes"on public.party_votes for select to authenticated using(public.is_persistent_party_member(party_id));
create policy "Party members can read vote options"on public.party_vote_options for select to authenticated using(exists(select 1 from public.party_votes vote where vote.id=vote_id and public.is_persistent_party_member(vote.party_id)));
create policy "Party members can read ballots"on public.party_vote_ballots for select to authenticated using(exists(select 1 from public.party_votes vote where vote.id=vote_id and public.is_persistent_party_member(vote.party_id)));

create or replace function public.party_vote_board(target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''stable as $$declare membership public.persistent_party_members%rowtype;board jsonb;begin select member.*into membership from public.persistent_party_members member join public.characters hero on hero.id=member.character_id where member.character_id=target_character_id and hero.user_id=auth.uid();if membership.id is null then raise exception'party membership not found';end if;select coalesce(jsonb_agg(jsonb_build_object('id',vote.id,'question',vote.question,'status',case when vote.status='open'and vote.closes_at<=now()then'expired'else vote.status end,'created_by_character_id',vote.created_by_character_id,'creator_name',creator.name,'closes_at',vote.closes_at,'created_at',vote.created_at,'winning_option_id',vote.winning_option_id,'options',(select coalesce(jsonb_agg(jsonb_build_object('id',option.id,'label',option.label,'position',option.position,'votes',(select count(*)from public.party_vote_ballots ballot where ballot.option_id=option.id),'selected_by_me',exists(select 1 from public.party_vote_ballots ballot where ballot.option_id=option.id and ballot.user_id=auth.uid()))order by option.position),'[]'::jsonb)from public.party_vote_options option where option.vote_id=vote.id))order by vote.created_at desc),'[]'::jsonb)into board from public.party_votes vote join public.characters creator on creator.id=vote.created_by_character_id where vote.party_id=membership.party_id;return jsonb_build_object('party_id',membership.party_id,'viewer_role',membership.role,'votes',board);end;$$;

create or replace function public.create_party_vote(target_character_id uuid,target_question text,target_options text[],target_duration_minutes integer default 30)returns jsonb language plpgsql security definer set search_path=''as $$declare membership public.persistent_party_members%rowtype;vote public.party_votes%rowtype;clean_options text[];option_label text;option_index integer:=0;begin select member.*into membership from public.persistent_party_members member join public.characters hero on hero.id=member.character_id where member.character_id=target_character_id and hero.user_id=auth.uid()and not exists(select 1 from public.character_life_profiles where character_id=hero.id and status<>'alive');if membership.id is null then raise exception'party membership not found';end if;if char_length(trim(coalesce(target_question,'')))not between 3 and 160 or coalesce(array_length(target_options,1),0)not between 2 and 4 or target_duration_minutes not between 5 and 1440 then raise exception'invalid vote';end if;select array_agg(left(trim(value),60))into clean_options from unnest(target_options)value;if exists(select 1 from unnest(clean_options)value where char_length(value)<1)or(select count(distinct lower(value))from unnest(clean_options)value)<>array_length(clean_options,1)then raise exception'invalid options';end if;insert into public.party_votes(party_id,created_by_user_id,created_by_character_id,question,closes_at)values(membership.party_id,auth.uid(),target_character_id,left(trim(target_question),160),now()+make_interval(mins=>target_duration_minutes))returning*into vote;foreach option_label in array clean_options loop option_index:=option_index+1;insert into public.party_vote_options(vote_id,label,position)values(vote.id,option_label,option_index);end loop;return public.party_vote_board(target_character_id);end;$$;

create or replace function public.cast_party_vote(target_character_id uuid,target_vote_id uuid,target_option_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare membership public.persistent_party_members%rowtype;vote public.party_votes%rowtype;begin select member.*into membership from public.persistent_party_members member join public.characters hero on hero.id=member.character_id where member.character_id=target_character_id and hero.user_id=auth.uid()and not exists(select 1 from public.character_life_profiles where character_id=hero.id and status<>'alive');if membership.id is null then raise exception'party membership not found';end if;select*into vote from public.party_votes where id=target_vote_id and party_id=membership.party_id for update;if vote.id is null then raise exception'vote not found';end if;if vote.status<>'open'or vote.closes_at<=now()then raise exception'vote closed';end if;if not exists(select 1 from public.party_vote_options where id=target_option_id and vote_id=vote.id)then raise exception'option not found';end if;insert into public.party_vote_ballots(vote_id,option_id,user_id,character_id)values(vote.id,target_option_id,auth.uid(),target_character_id)on conflict(vote_id,user_id)do update set option_id=excluded.option_id,character_id=excluded.character_id,voted_at=now();return public.party_vote_board(target_character_id);end;$$;

create or replace function public.close_party_vote(target_character_id uuid,target_vote_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare membership public.persistent_party_members%rowtype;vote public.party_votes%rowtype;winner uuid;top_count bigint;tie_count bigint;begin select member.*into membership from public.persistent_party_members member join public.characters hero on hero.id=member.character_id where member.character_id=target_character_id and hero.user_id=auth.uid();if membership.id is null then raise exception'party membership not found';end if;select*into vote from public.party_votes where id=target_vote_id and party_id=membership.party_id for update;if vote.id is null then raise exception'vote not found';end if;if vote.status<>'open'then raise exception'vote closed';end if;if membership.role<>'leader'and vote.created_by_user_id<>auth.uid()then raise exception'vote owner required';end if;select option.id,count(ballot.id)into winner,top_count from public.party_vote_options option left join public.party_vote_ballots ballot on ballot.option_id=option.id where option.vote_id=vote.id group by option.id,option.position order by count(ballot.id)desc,option.position limit 1;select count(*)into tie_count from(select option.id from public.party_vote_options option left join public.party_vote_ballots ballot on ballot.option_id=option.id where option.vote_id=vote.id group by option.id having count(ballot.id)=top_count)tied;if top_count=0 or tie_count>1 then winner:=null;end if;update public.party_votes set status='closed',winning_option_id=winner,closed_at=now()where id=vote.id;return public.party_vote_board(target_character_id);end;$$;
revoke all on function public.party_vote_board(uuid)from public;revoke all on function public.create_party_vote(uuid,text,text[],integer)from public;revoke all on function public.cast_party_vote(uuid,uuid,uuid)from public;revoke all on function public.close_party_vote(uuid,uuid)from public;grant execute on function public.party_vote_board(uuid)to authenticated;grant execute on function public.create_party_vote(uuid,text,text[],integer)to authenticated;grant execute on function public.cast_party_vote(uuid,uuid,uuid)to authenticated;grant execute on function public.close_party_vote(uuid,uuid)to authenticated;
alter publication supabase_realtime add table public.party_votes;alter publication supabase_realtime add table public.party_vote_ballots;
